<template><aside v-if="context" class="support-launcher" aria-label="Soporte y avisos">
 <section v-if="urgentTotal" class="support-urgent-banner" role="alert"><strong>{{urgentTotal}} {{urgentTotal===1?'ticket urgente pendiente de aceptar':'tickets urgentes pendientes de aceptar'}}</strong><p v-if="urgentTickets.length">{{urgentTickets[0].code}} · {{urgentTickets[0].subject}}</p><small>El aviso se repite cada minuto hasta aceptar la atención. Cerrar un mensaje no acepta el ticket.</small><div><button v-if="urgentTickets.length && (!urgentTickets[0].technician_id || Number(urgentTickets[0].technician_id)===Number(context.principal))" type="button" :disabled="alertAccepting" @click="acceptUrgent">{{alertAccepting?'Aceptando…':'Aceptar ticket'}}</button><button type="button" @click="openTicket(urgentTickets[0].ticket_id)">Ver ticket</button><button type="button" @click="toggleSound">{{soundEnabled?'Silenciar sonido y voz':'Activar sonido y voz'}}</button></div><p v-if="error">{{error}}</p></section>
 <section v-if="toast && !panel && !createOpen && !portalOpen" class="support-alert-toast" :style="panelPosition" role="status"><strong>{{label(toast.kind)}}</strong><p>{{toast.code}} · {{toast.subject}}</p><p v-if="toast.assigned_name">Te atiende: <strong>{{toast.assigned_name}}</strong><br v-if="toast.expected_resolution_at"><span v-if="toast.expected_resolution_at">Solución estimada: {{formatEstimate(toast.expected_resolution_at)}}</span></p><div><button type="button" @click="openTicket(toast.ticket_id)">Ver ticket</button><button type="button" @click="toast=null">Cerrar aviso</button></div></section>
 <section v-if="panel" class="support-launcher-panel" :style="panelPosition"><header><strong>Tu centro de soporte</strong><button type="button" @click="panel=false" aria-label="Cerrar soporte">×</button></header><p class="support-launcher-hint">Arrastra el botón para moverlo o usa las flechas del teclado. Puedes pegarlo al borde para ocupar menos espacio.</p><button type="button" @click="toggleDock">{{docked?'Despegar del marco':'Pegar al marco'}}</button><div class="support-launcher-actions"><button type="button" @click="newTicket">+ Crear ticket rápido</button><button type="button" @click="openPortal()">Ver tickets</button></div><button type="button" class="support-sound-button" :aria-pressed="soundEnabled?'true':'false'" @click="toggleSound">{{soundEnabled?'Sonido y voz de avisos activados':'Activar sonido y voz de avisos'}}</button><p v-if="error" role="alert">{{error}}</p><p class="support-launcher-hint">{{unread}} avisos sin leer · Se actualiza cada 20 segundos con el sistema abierto.</p><div class="support-launcher-inbox"><button v-for="n in notifications" :key="n.id" type="button" @click="openTicket(n.ticket_id)"><strong>{{label(n.kind)}} · {{n.code}}</strong><span>{{n.subject}}</span></button><p v-if="!notifications.length">No tienes avisos pendientes.</p></div></section>
 <div v-if="!createOpen && !portalOpen" ref="floatControl" class="support-float-control" :class="{'is-docked':docked,'is-right':dockSide==='right','is-dragging':dragging}" :style="floatPosition" @pointerdown="startDrag"><button type="button" class="support-floating-button" title="Arrastra para mover; pulsa para abrir soporte" @keydown="moveWithKeys" :aria-expanded="panel?'true':'false'" aria-label="Abrir soporte y crear ticket" @click="togglePanel"><svg viewBox="0 0 32 32" width="28" height="28" aria-hidden="true"><path d="M6 18v-3a10 10 0 0120 0v3M6 16H4v9h5v-9H6zm20 0h2v9h-5v-9h3zm0 9c0 3-4 4-8 4" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg><span>Soporte</span><b v-if="unread">{{unread>99?'99+':unread}}</b></button><button type="button" class="support-dock-button" :aria-label="docked?'Despegar soporte del marco':'Pegar soporte al marco'" :title="docked?'Despegar del marco':'Pegar al marco'" :aria-pressed="docked?'true':'false'" @pointerdown.stop @click.stop="toggleDock">{{docked?'↗':'⇥'}}</button></div>
 <b-modal v-model="createOpen" title="Reportar un problema" modal-class="diary-modal-premium" hide-footer size="lg"><form class="support-quick-form" @submit.prevent="create"><p>Te ayudaremos con gusto. Tu usuario y empresa se reconocen automáticamente.</p><p v-if="formError" class="support-quick-error" role="alert">{{formError}}</p><label>¿Qué necesitas resolver?<input v-model="form.subject" required maxlength="180" placeholder="Describe brevemente el problema"></label><label>Detalle<textarea v-model="form.description" required rows="4" maxlength="20000" placeholder="Indica qué ocurrió y qué necesitas hacer. No incluyas contraseñas ni claves."></textarea></label><div class="support-quick-grid"><label>Categoría<select v-model="form.category_id" required><option value="">Seleccionar</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Prioridad<select v-model="form.priority"><option value="low">Baja · Consulta</option><option value="medium">Media · Puedo continuar</option><option value="high">Alta · Función bloqueada</option><option value="critical">Urgente · No puedo facturar</option></select></label></div><label>Módulo afectado<input v-model="form.module" required maxlength="100"></label><button type="submit" :disabled="saving">{{saving?'Enviando…':'Enviar ticket a soporte'}}</button></form></b-modal>
 <b-modal v-model="portalOpen" title="Centro de soporte" size="xl" hide-footer modal-class="support-portal-modal" @hidden="poll"><iframe v-if="portalOpen" :src="portalUrl" title="Tickets y atención de soporte" class="support-portal-frame"></iframe></b-modal>
</aside></template>
<script>
import config from '@/store/config';
import {urgentReminderMs,pendingUrgentTickets,urgentAnnouncement} from '@/utils/supportUrgency';
export default {data(){return {context:null,urgentTickets:[],urgentTotal:0,alertAccepting:false,panel:false,toast:null,notifications:[],unread:0,error:'',formError:'',saving:false,createOpen:false,form:{},portalOpen:false,portalUrl:'',soundEnabled:false,floatX:0,floatY:96,docked:true,dockSide:'left',dragging:false,viewportW:window.innerWidth,viewportH:window.innerHeight}},computed:{floatPosition(){return {left:this.floatX+'px',top:this.floatY+'px'}},panelPosition(){const width=Math.min(360,this.viewportW-24),height=Math.min(430,this.viewportH-24);const left=Math.max(12,Math.min(this.floatX,this.viewportW-width-12));const top=this.floatY>this.viewportH/2?Math.max(12,this.floatY-height-12):Math.min(this.floatY+64,Math.max(12,this.viewportH-height-12));return {left:left+'px',top:top+'px',right:'auto',bottom:'auto',maxHeight:Math.max(100,this.viewportH-top-12)+'px'}},categories(){return this.context?this.context.categories.filter(c=>Number(c.active)):[]}},mounted(){this._dragMove=e=>this.dragMove(e);this._dragEnd=e=>this.endDrag(e);this._resize=()=>this.clampPosition();window.addEventListener('pointermove',this._dragMove,{passive:false});window.addEventListener('pointerup',this._dragEnd);window.addEventListener('pointercancel',this._dragEnd);window.addEventListener('resize',this._resize);this.init();this._focus=()=>this.poll();window.addEventListener('focus',this._focus);this._unlock=()=>this.unlockAudio();window.addEventListener('pointerdown',this._unlock);this.$root.$on('support:changed',this.poll);this.$root.$on('support:quick-create',this.newTicket)},beforeDestroy(){this._drag=null;window.removeEventListener('pointermove',this._dragMove);window.removeEventListener('pointerup',this._dragEnd);window.removeEventListener('pointercancel',this._dragEnd);window.removeEventListener('resize',this._resize);clearInterval(this._timer);clearTimeout(this._toastTimer);clearTimeout(this._urgentTimer);window.removeEventListener('focus',this._focus);window.removeEventListener('pointerdown',this._unlock);this.$root.$off('support:changed',this.poll);this.$root.$off('support:quick-create',this.newTicket);if(this._audio)this._audio.close()},methods:{
 controlSize(){const el=this.$refs.floatControl;return el?{w:el.offsetWidth,h:el.offsetHeight}:{w:this.docked?64:180,h:50}},
 clampPosition(){this.viewportW=window.innerWidth;this.viewportH=window.innerHeight;const size=this.controlSize();this.floatY=Math.max(8,Math.min(this.floatY,this.viewportH-size.h-8));this.floatX=this.docked?(this.dockSide==='right'?Math.max(0,this.viewportW-size.w):0):Math.max(8,Math.min(this.floatX,this.viewportW-size.w-8))},
 restorePosition(){try{const v=JSON.parse(localStorage.getItem('support:position:'+this.context.principal)||'null');if(v&&Number.isFinite(v.x)&&Number.isFinite(v.y)){this.floatX=v.x;this.floatY=v.y;this.docked=!!v.docked;this.dockSide=v.side==='right'?'right':'left'}}catch(e){}},
 savePosition(){if(this.context)try{localStorage.setItem('support:position:'+this.context.principal,JSON.stringify({x:this.floatX,y:this.floatY,docked:this.docked,side:this.dockSide}))}catch(e){}},
 togglePanel(){if(this._suppressClick)return;this.panel=!this.panel},
 toggleDock(){this.panel=false;this.docked=!this.docked;if(this.docked)this.dockSide=this.floatX+this.controlSize().w/2>this.viewportW/2?'right':'left';else this.floatX=this.dockSide==='right'?Math.max(8,this.viewportW-180):18;this.$nextTick(()=>{this.clampPosition();this.savePosition()})},
 startDrag(e){if(e.button!==0||e.target.closest('.support-dock-button'))return;const size=this.controlSize();this._drag={id:e.pointerId,x:e.clientX,y:e.clientY,left:this.floatX,top:this.floatY,w:size.w,h:size.h,target:e.currentTarget,moved:false}},
 dragMove(e){const d=this._drag;if(!d||d.id!==e.pointerId)return;const dx=e.clientX-d.x,dy=e.clientY-d.y;if(!d.moved&&Math.hypot(dx,dy)<6)return;if(!d.moved){d.moved=true;this.dragging=true;this.panel=false;try{d.target.setPointerCapture(e.pointerId)}catch(err){}}e.preventDefault();this.floatY=Math.max(8,Math.min(d.top+dy,window.innerHeight-d.h-8));if(this.docked){this.dockSide=e.clientX>window.innerWidth/2?'right':'left';this.floatX=this.dockSide==='right'?Math.max(0,window.innerWidth-d.w):0}else this.floatX=Math.max(8,Math.min(d.left+dx,window.innerWidth-d.w-8))},
 endDrag(e){const d=this._drag;if(!d||d.id!==e.pointerId)return;this._drag=null;this.dragging=false;if(d.moved){this._suppressClick=true;setTimeout(()=>{this._suppressClick=false},300);this.clampPosition();this.savePosition()}try{if(d.target.hasPointerCapture(e.pointerId))d.target.releasePointerCapture(e.pointerId)}catch(err){}},
 moveWithKeys(e){if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const delta=e.shiftKey?30:10;if(e.key==='ArrowUp')this.floatY-=delta;if(e.key==='ArrowDown')this.floatY+=delta;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){this.docked=false;this.floatX+=e.key==='ArrowRight'?delta:-delta}this.$nextTick(()=>{this.clampPosition();this.savePosition()})},
 async init(){try{const data=(await this.axios.get(config.API+'support/context',{timeout:10000})).data;if(!data||!data.user||!Array.isArray(data.categories))return;this.context=data;this.restorePosition();this.$nextTick(()=>this.clampPosition());try{this._lastAlert=Number(localStorage.getItem('support:lastAlert:'+this.context.principal))||0;const savedSound=localStorage.getItem('support:sound:'+this.context.principal);this.soundEnabled=savedSound===null?localStorage.getItem('diario:voice:'+this.context.user)==='1':savedSound==='1'}catch(e){}await this.poll();this._timer=setInterval(this.poll,20000)}catch(e){}},
 formatEstimate(value){return new Intl.DateTimeFormat('es-PE',{dateStyle:'short',timeStyle:'short',timeZone:'America/Lima'}).format(new Date(value.replace(' ','T')+'-05:00'))},label(kind){return {sent:'Ticket enviado al equipo',new_ticket:'Nuevo ticket de soporte',assigned:'Ticket asignado',new_message:'Nueva respuesta',internal_message:'Nueva nota del equipo',resolved:'Solución lista · Confirma y califica',status_changed:'Actualización del ticket',rated:'El cliente calificó la atención'}[kind]||'Aviso de soporte'},
 async poll(){if(!this.context||this._polling)return;this._polling=true;try{const r=(await this.axios.get(config.API+'support/notifications',{timeout:10000})).data;this.notifications=r.notifications||[];this.unread=Number(r.unread)||0;this.urgentTickets=pendingUrgentTickets(r.urgent_tickets);this.urgentTotal=Number(r.urgent_total)||this.urgentTickets.length;this.error='';const latest=this.notifications[0];if(latest&&Number(latest.id)>(this._lastAlert||0)){this._lastAlert=Number(latest.id);try{localStorage.setItem('support:lastAlert:'+this.context.principal,String(this._lastAlert))}catch(e){}this.toast=latest;clearTimeout(this._toastTimer);this._toastTimer=setTimeout(()=>{this.toast=null},15000);if(!this.urgentTotal)this.beep()}if(this.urgentTotal){await this.announceUrgent();this.scheduleUrgent();}else{clearTimeout(this._urgentTimer);try{localStorage.removeItem('support:urgent-last:'+this.context.principal)}catch(e){}}}catch(e){this.error='No se pudieron actualizar los avisos.'}finally{this._polling=false}},
 scheduleUrgent(){clearTimeout(this._urgentTimer);if(!this.soundEnabled||!this.urgentTickets.length||!this._audio||this._audio.state!=='running')return;let last=this._urgentLast||0;try{last=Math.max(last,Number(localStorage.getItem('support:urgent-last:'+this.context.principal))||0)}catch(e){}this._urgentTimer=setTimeout(()=>this.poll(),Math.max(250,last+urgentReminderMs-Date.now()));},
 async announceUrgent(){if(!this.soundEnabled||!this.urgentTickets.length||!this._audio||this._audio.state!=='running')return;const announce=()=>{const key='support:urgent-last:'+this.context.principal,now=Date.now();let last=this._urgentLast||0;try{last=Math.max(last,Number(localStorage.getItem(key))||0)}catch(e){}if(now-last<urgentReminderMs)return;this._urgentLast=now;try{localStorage.setItem(key,String(now))}catch(e){}this.beep();this.speakUrgent(urgentAnnouncement(this.urgentTotal,this.urgentTickets[0]));};if(navigator.locks&&navigator.locks.request)await navigator.locks.request('support-urgent:'+this.context.principal,announce);else announce()},
 speakUrgent(text){if(!this.soundEnabled||!window.speechSynthesis||!window.SpeechSynthesisUtterance)return;const synth=window.speechSynthesis;if(synth.speaking||synth.pending)return;const speech=new window.SpeechSynthesisUtterance(text);speech.lang='es-PE';speech.rate=1;const voices=synth.getVoices();speech.voice=voices.find(v=>v.lang==='es-PE')||voices.find(v=>/^es/i.test(v.lang))||null;synth.speak(speech)},
 async acceptUrgent(){if(this.alertAccepting||!this.urgentTickets.length)return;this.alertAccepting=true;this.error='';const ticket=this.urgentTickets[0];try{const assigned=Number(ticket.technician_id);const action=assigned?'transition':'assign';const body=assigned?{id:ticket.ticket_id,version:ticket.version,status:'in_progress',reason:'Ticket urgente aceptado para atención'}:{id:ticket.ticket_id,technician:Number(this.context.principal)};await this.axios.post(config.API+'support/'+action,body,{headers:{'X-Support-CSRF':this.context.csrf},timeout:15000});await this.poll();this.$root.$emit('support:changed')}catch(e){this.error=e.response&&e.response.data&&e.response.data.error||'No se pudo aceptar. Actualiza el ticket antes de repetir.';await this.poll()}finally{this.alertAccepting=false}},
 unlockAudio(){if(!this.soundEnabled)return;const Audio=window.AudioContext||window.webkitAudioContext;if(Audio&&!this._audio)this._audio=new Audio();if(this._audio&&this._audio.state==='suspended')this._audio.resume().then(()=>{this.announceUrgent();this.scheduleUrgent()}).catch(()=>{})},
 toggleSound(){clearTimeout(this._urgentTimer);this.soundEnabled=!this.soundEnabled;try{localStorage.setItem('support:sound:'+this.context.principal,this.soundEnabled?'1':'0')}catch(e){}if(this.soundEnabled){const Audio=window.AudioContext||window.webkitAudioContext;if(Audio&&!this._audio)this._audio=new Audio();if(this._audio)this._audio.resume().then(()=>{this.beep();if(this.urgentTotal){this.announceUrgent();this.scheduleUrgent()}else this.speakUrgent('Sonido y voz de tickets activados.')}).catch(()=>{})}},beep(){if(!this.soundEnabled||!this._audio||this._audio.state!=='running')return;const ctx=this._audio,o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=740;g.gain.setValueAtTime(.08,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.2);o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+.2)},
 newTicket(){this.panel=false;this.formError='';this.form={subject:'',description:'',category_id:'',priority:'medium',module:this.$route.name==='Ventas'?'Punto de venta':this.$route.name==='DiarioActividades'?'Programación y soporte':this.$route.name==='CentroSoporte'?'General':this.$route.name||'General'};this.createOpen=true},
 async create(){if(this.saving)return;this.saving=true;this.formError='';try{const result=(await this.axios.post(config.API+'support/create',this.form,{headers:{'X-Support-CSRF':this.context.csrf},timeout:20000})).data;this.createOpen=false;this.toast={ticket_id:result.id,kind:'sent',code:result.code,subject:'Recibimos tu solicitud. Gracias por avisarnos; el equipo podrá atenderla.'};clearTimeout(this._toastTimer);this._toastTimer=setTimeout(()=>{this.toast=null},15000);this.$root.$emit('support:changed');}catch(e){this.formError=e.response&&e.response.data&&e.response.data.error||'No se pudo enviar. Revisa tus tickets antes de volver a intentarlo.'}finally{this.saving=false}},
 openTicket(id){this.toast=null;this.openPortal(id)},openPortal(id){this.panel=false;if(this.$route.path==='/soporte'){this.$router.push({path:'/soporte',query:id?{ticket:String(id)}:{}},()=>{},()=>{});return;}const base='/support-ui/index.html';this.portalUrl=base+'#/soporte'+(id?'?ticket='+encodeURIComponent(id):'');this.portalOpen=true}
}};
</script>
<style>
.support-urgent-banner{position:fixed;right:18px;top:108px;width:420px;max-width:calc(100vw - 36px);z-index:13005;padding:18px;border:2px solid #d84242;border-radius:14px;background:#fff2f2;color:#722632;box-shadow:0 8px 28px #36131f33;font:15px/1.4 Arial,sans-serif}.support-urgent-banner p{margin:8px 0;overflow-wrap:anywhere}.support-urgent-banner small{display:block}.support-urgent-banner>div{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.support-urgent-banner button{padding:9px 11px;border:1px solid #c65a65;border-radius:7px;background:white;color:#742933;font-weight:bold}.support-urgent-banner button:first-child{background:#a42e43;color:white}.support-floating-button{position:fixed;right:20px;bottom:100px;z-index:13000;display:flex;align-items:center;gap:9px;padding:13px 18px;border:1px solid #a0ecdf;border-radius:30px;background:linear-gradient(135deg,#087f80,#1463bf);color:white;font:600 15px "Segoe UI",Arial;box-shadow:0 6px 22px #154c7950;cursor:pointer;min-height:52px}.support-floating-button b{position:absolute;top:-7px;right:-4px;padding:4px 6px;min-width:23px;border-radius:13px;background:#d52f52;border:2px solid white;color:white;font-size:12px}.support-launcher-panel,.support-alert-toast{position:fixed;right:20px;bottom:165px;width:360px;max-width:calc(100vw - 24px);max-height:65vh;overflow:auto;z-index:13001;background:white;color:#244360;border:1px solid #c4d8ed;border-radius:17px;padding:18px;box-shadow:0 12px 40px #153c6640;font:15px/1.5 "Segoe UI",Arial}.support-launcher-panel>header{display:flex;align-items:center;justify-content:space-between;gap:10px}.support-launcher-panel button,.support-alert-toast button,.support-quick-form button{font:600 14px "Segoe UI",Arial;min-height:40px;border:1px solid #c7d9ec;border-radius:9px;background:#f0f6ff;color:#2c5790;padding:9px 12px;cursor:pointer}.support-launcher-panel>header>button{font-size:22px;min-width:40px;background:white}.support-launcher-actions,.support-alert-toast>div{display:flex;gap:8px;margin-top:12px;flex-wrap:wrap}.support-launcher-actions>button:first-child,.support-quick-form>button{background:#087f75;color:white;border-color:#087f75}.support-sound-button{margin-top:10px}.support-launcher-hint{font-size:12px;color:#617c95}.support-launcher-inbox>button{display:block;width:100%;text-align:left;margin:8px 0;background:#f4f8fe;overflow-wrap:anywhere}.support-launcher-inbox strong,.support-launcher-inbox span{display:block}.support-launcher-inbox strong{font-size:13px}.support-launcher-inbox span{font-weight:400;font-size:14px;margin-top:4px}.support-alert-toast{border-left:5px solid #0ba68b;z-index:13002}.support-alert-toast>p{overflow-wrap:anywhere}.support-launcher-panel~.support-alert-toast{display:none}.support-quick-form{display:grid;gap:16px;color:#294967;font:15px/1.5 "Segoe UI",Arial}.support-quick-form label{font-weight:600}.support-quick-form input,.support-quick-form textarea,.support-quick-form select{display:block;width:100%;margin-top:6px;padding:12px;border:1px solid #c2d5e7;border-radius:9px;font:16px "Segoe UI",Arial;color:#294967;background:white}.support-quick-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.support-quick-error{background:#ffe7e9;color:#a3384c;padding:12px;border-radius:9px}.support-portal-modal .modal-dialog{max-width:1200px;width:calc(100vw - 24px)}.support-portal-modal .modal-body{padding:0}.support-portal-frame{width:100%;height:75vh;border:0;display:block}.support-launcher button:focus-visible{outline:3px solid #5a95ec;outline-offset:3px}@media(max-width:700px){.support-floating-button{right:12px;bottom:116px;padding:12px 15px}.support-launcher-panel,.support-alert-toast{right:12px;bottom:180px;max-height:60vh}.support-quick-grid{grid-template-columns:1fr}.support-portal-modal .modal-dialog{margin:12px;max-width:none}.support-portal-frame{height:78vh}}
</style>
<style src="../assets/css/support-floating.css"></style>
